// ═══ COMPARISON TABLE ═══
//
// Feature              HashMap           Hashtable         ConcurrentHashMap
// Thread-safe          NO                YES (coarse)      YES (fine-grained)
// Null key             1 allowed         NOT allowed       NOT allowed
// Null value           Multiple allowed  NOT allowed       NOT allowed
// Locking              None              entire table      per-bucket (Java 8+)
// Performance          Fastest (no sync) SLOW (one lock)   Fast (concurrent)
// Since                Java 1.2          Java 1.0          Java 1.5
// Iterator             fail-fast         fail-fast (enum)  weakly consistent
// Recommendation       single-threaded   (Avoid) NEVER          multi-threaded (Recommended) 

// ═══ WHY Hashtable is SLOW ═══
// Every method synchronized on the SAME lock (this):
public class Hashtable<K,V> {
    public synchronized V get(Object key) { ... }   // locked!
    public synchronized V put(K key, V value) { ... } // locked!
    public synchronized int size() { ... }            // even size()!
}
// 10 threads reading different keys? → queued behind ONE lock!

// ═══ WHY ConcurrentHashMap is FAST ═══
// Java 8+: array of bins (buckets). Each bin locked independently.
// Reads: NO locking at all! Uses volatile reads.
// Writes: synchronized only on the SPECIFIC bin being modified.
// 10 threads writing to different bins? → all proceed in parallel!

ConcurrentHashMap<String, BigDecimal> balances = new ConcurrentHashMap<>();
balances.put("SAV2001", new BigDecimal("75000"));
balances.get("SAV2001");  // NO lock! Volatile read.
// Two threads putting to different buckets → concurrent, no contention!

// ═══ NULL HANDLING ═══
HashMap<String, String> hm = new HashMap<>();
hm.put(null, "null-key-value");   // (Recommended) allowed!
hm.put("key", null);              // (Recommended) allowed!

// Hashtable<String, String> ht = new Hashtable<>();
// ht.put(null, "value");   // (Avoid) NullPointerException!
// ht.put("key", null);     // (Avoid) NullPointerException!

// ConcurrentHashMap<String, String> chm = new ConcurrentHashMap<>();
// chm.put(null, "value");  // (Avoid) NullPointerException!
// chm.put("key", null);    // (Avoid) NullPointerException!
// WHY no null in CHM? Because get() returning null is ambiguous:
// Does key not exist, or does key map to null? Can't tell in concurrent context.

// ═══ ATOMIC OPERATIONS (ConcurrentHashMap) ═══
ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();
counts.merge("SAV2001", 1, Integer::sum);    // atomic increment!
counts.computeIfAbsent("CUR3001", k -> 0);   // atomic insert if missing
counts.compute("SAV2001", (k, v) -> v + 1);  // atomic update
// All atomic — no external synchronization needed!
