// ─── File: src/test/java/com/bank/maps/MapComparisonTest.java ───
package com.bank.maps;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class MapComparisonTest {

    // ═══ HashMap: allows null key and values ═══
    @Test
    void hashMap_allowsNull() {
        Map<String, String> map = new HashMap<>();
        map.put(null, "null-key");
        map.put("key", null);
        assertThat(map.get(null)).isEqualTo("null-key");
        assertThat(map.get("key")).isNull();
    }

    // ═══ Hashtable: rejects null ═══
    @Test
    void hashtable_rejectsNull() {
        Hashtable<String, String> ht = new Hashtable<>();
        assertThatThrownBy(() -> ht.put(null, "value"))
            .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> ht.put("key", null))
            .isInstanceOf(NullPointerException.class);
    }

    // ═══ ConcurrentHashMap: rejects null ═══
    @Test
    void concurrentHashMap_rejectsNull() {
        ConcurrentHashMap<String, String> chm = new ConcurrentHashMap<>();
        assertThatThrownBy(() -> chm.put(null, "value"))
            .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> chm.put("key", null))
            .isInstanceOf(NullPointerException.class);
    }

    // ═══ ConcurrentHashMap: atomic operations ═══
    @Test
    void concurrentHashMap_atomicOps() {
        ConcurrentHashMap<String, Integer> txnCounts = new ConcurrentHashMap<>();

        // computeIfAbsent: atomic insert if missing
        txnCounts.computeIfAbsent("SAV2001", k -> 0);
        assertThat(txnCounts.get("SAV2001")).isEqualTo(0);

        // merge: atomic increment
        txnCounts.merge("SAV2001", 1, Integer::sum);
        txnCounts.merge("SAV2001", 1, Integer::sum);
        assertThat(txnCounts.get("SAV2001")).isEqualTo(2);
    }

    // ═══ ConcurrentHashMap: thread-safe concurrent access ═══
    @Test
    void concurrentHashMap_threadSafe() throws InterruptedException {
        ConcurrentHashMap<String, AtomicInteger> map = new ConcurrentHashMap<>();
        map.put("counter", new AtomicInteger(0));

        int threads = 10, incrementsPerThread = 10_000;
        ExecutorService executor = Executors.newFixedThreadPool(threads);

        for (int t = 0; t < threads; t++) {
            executor.submit(() -> {
                for (int i = 0; i < incrementsPerThread; i++) {
                    map.get("counter").incrementAndGet();
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);

        assertThat(map.get("counter").get()).isEqualTo(threads * incrementsPerThread);
        // 100,000 — all increments accounted for! Thread-safe!
    }

    // ═══ Performance: ConcurrentHashMap vs Hashtable ═══
    @Test
    void performance_chmVsHashtable() {
        int n = 200_000;

        Hashtable<Integer, Integer> ht = new Hashtable<>();
        long t1 = System.nanoTime();
        for (int i = 0; i < n; i++) ht.put(i, i);
        for (int i = 0; i < n; i++) ht.get(i);
        long htMs = (System.nanoTime() - t1) / 1_000_000;

        ConcurrentHashMap<Integer, Integer> chm = new ConcurrentHashMap<>();
        long t2 = System.nanoTime();
        for (int i = 0; i < n; i++) chm.put(i, i);
        for (int i = 0; i < n; i++) chm.get(i);
        long chmMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("Hashtable: " + htMs + "ms, ConcurrentHashMap: " + chmMs + "ms");
    }
}
